using System.Numerics;
using System.Linq;
using System;
using XLinUI;
var s=new ChatVisibilityState();
void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS: "+name);}
Check(s.Change("chat",1,2,true,true)==false,"hide visible window");
s.Change("chat",1,2,false,true);
Check(s.Change("chat",1,2,false,false)==true,"restore original visibility after repeated frames");
Check(s.Change("chat",1,2,true,false)==null,"do not touch unowned windows");
s.Change("chat",1,2,false,true);
Check(s.Change("chat",1,2,false,false)==false,"preserve originally hidden window");
s.Change("chat",1,2,true,true);
Check(s.Change("chat",3,4,false,false)==null,"never apply stale snapshot to recreated addon");
s.Change("chat",1,2,true,true);s.Forget("chat");
Check(s.Change("chat",1,2,false,false)==null,"finalized addon releases snapshot");
s.Change("chat",1,2,true,true);s.Change("chat",0,0,false,true);
Check(s.Change("chat",1,2,false,false)==null,"missing addon releases snapshot");

var all = new ChatVisibilityState();
all.Change("one",11,12,true,true);all.Change("two",21,22,false,true);
Check(all.Change("one",11,12,false,false)==true && all.Change("two",21,22,false,false)==false,"restore mixed original window states");
var chat = new ChatVisibilityState();
var current=all.Change("chat",1,2,true,true)!.Value;
current=all.Change("chat",1,2,current,false)!.Value;
current=chat.Change("chat",1,2,current,true)!.Value;
Check(chat.Change("chat",1,2,current,false)==true,"release global owner before chat-only hiding");

Check(!GameUiVisibilityPolicy.ShouldHide("_ActionBar",true,true,true,true) && !GameUiVisibilityPolicy.ShouldHide("_ActionBar09",true,true,true,true),"preserve multiple native hotbars");
Check(!GameUiVisibilityPolicy.ShouldHide("_Status",true,true,true,true) && !GameUiVisibilityPolicy.ShouldHide("_JobHudSAM0",true,true,true,true),"preserve buffs and job gauges");
Check(!GameUiVisibilityPolicy.ShouldHide("_ActionCross",true,true,true,true) && !GameUiVisibilityPolicy.ShouldHide("_PartyList",true,true,true,true),"preserve cross hotbars and party");
Check(GameUiVisibilityPolicy.ShouldHide("_Parameter",false,true,true,false),"replace only the native resource panel");
Check(!GameUiVisibilityPolicy.ShouldHide("_Parameter",false,true,false,false),"restore resources when replacement disabled");
Check(GameUiVisibilityPolicy.ShouldHide("_DTR",false,true,false,true),"replace native server info with custom toolbar");
Check(!GameUiVisibilityPolicy.ShouldHide("Inventory",false,true,true,true),"keep ordinary native windows in original UI mode");
Check(GameUiVisibilityPolicy.ShouldHide("_ActionBar",true,false,false,false),"legacy full-hide remains opt-in");

Check(HudGeometry.IsStandardHotbar("_ActionBar") && HudGeometry.IsStandardHotbar("_ActionBar01") && HudGeometry.IsStandardHotbar("_ActionBar09"), "detect primary and all numbered standard bars");
Check(!HudGeometry.IsStandardHotbar("_ActionBar10") && !HudGeometry.IsStandardHotbar("_ActionBarFoo") && !HudGeometry.IsStandardHotbar("_ActionBar00"), "reject unsupported addon names without unsafe casts");
Check(HudGeometry.Valid(new System.Numerics.Vector2(-20, 40), new System.Numerics.Vector2(44, 88)), "allow partially off-screen native slots");
Check(!HudGeometry.Valid(new System.Numerics.Vector2(float.NaN, 0), new System.Numerics.Vector2(44)) && !HudGeometry.Valid(System.Numerics.Vector2.Zero, new System.Numerics.Vector2(0, 40)), "reject malformed slot bounds");
Check(!GameUiVisibilityPolicy.ShouldHide("_ActionBar09",true,false,false,false,true),"styled native bars survive legacy hide mode");
Check(!GameUiVisibilityPolicy.ShouldHide("_NaviMap",true,false,false,false,false,true),"square minimap survives global hide");

var appearance = new NativeAppearanceState();
var initial = new NativeAppearance(255,100,110,120);var custom = new NativeAppearance(80,40,50,60);
appearance.Change("Inventory",1,2,initial,custom);appearance.Change("Inventory",1,2,custom,custom);
Check(appearance.Change("Inventory",1,2,custom,null)==initial,"restore original native color and alpha after repeated styling");
appearance.Change("Inventory",1,2,initial,custom);
Check(appearance.Change("Inventory",3,2,custom,null)==null,"do not restore colors across recreated addon identity");
appearance.Change("Inventory",1,2,initial,custom);appearance.Forget("Inventory");
Check(appearance.Change("Inventory",1,2,custom,null)==null,"forget colors before native addon finalization");
appearance.Change("A",1,2,initial,custom);appearance.Change("A",1,3,initial with {Alpha=0},custom);
Check(appearance.Change("A",1,3,custom,null)?.Alpha==0 && appearance.Change("A",1,2,custom,null)==initial,"restore separate nodes including originally transparent decorations");

Check(HudReplacementPolicy.ShouldHide("_TargetInfoMainTarget",HudReady.Target) && HudReplacementPolicy.ShouldHide("_TargetInfoBuffDebuff",HudReady.Target),"hide complete target UI only after its replacement draws");
Check(!HudReplacementPolicy.ShouldHide("_TargetInfo",HudReady.None) && !HudReplacementPolicy.ShouldHide("_FocusTargetInfo",HudReady.Target),"missing or unrelated replacement preserves native HUD");
Check(HudReplacementPolicy.ShouldHide("_CastBar",HudReady.PlayerCast) && !HudReplacementPolicy.ShouldHide("_CastBar",HudReady.Target),"player casting has independent readiness");
Check(HudReplacementPolicy.ShouldHide("_StatusAilments",HudReady.Statuses) && !HudReplacementPolicy.ShouldHide("_StatusCustom0",HudReady.Statuses),"standard status groups replaced while custom groups stay untouched");
Check(!HudReplacementPolicy.ShouldHide("_PartyList",HudReady.Target|HudReady.Statuses),"party remains native unless a full replacement declares readiness");
Check(HudReplacementPolicy.ShouldHide("_Parameter",HudReady.Resources) && !HudReplacementPolicy.ShouldHide("_Parameter",HudReady.None),"resources stay visible when custom resource window fails");
Check(HudReplacementPolicy.ShouldHide("_DTR",HudReady.Top) && !HudReplacementPolicy.ShouldHide("_DTR",HudReady.None),"server bar restoration follows actual toolbar rendering");
Check(HudValues.Ratio(200,100)==1 && HudValues.Ratio(1,0)==0 && HudValues.Ratio(float.NaN,10)==0,"bound HP and cast progress with invalid values");
Check(HudValues.Duration(59.1f)=="60" && HudValues.Duration(61)=="2m" && HudValues.Duration(0)=="∞","status duration handles seconds minutes and indefinite effects");
Check(!HudValues.ValidCast(float.NaN,2) && !HudValues.ValidCast(1,0) && HudValues.ValidCast(1,2),"invalid cast data preserves native cast display");

Check(SurfacePolicy.PanelAlpha(true,false,true,1)==0,"forced transparent panels override full opacity without text-only mode");
Check(SurfacePolicy.NativeAlpha(255,true,false,true,1)==0,"native background becomes transparent independently of its opacity slider");
Check(SurfacePolicy.NativeAlpha(100,false,false,true,.5f)==50,"native transparency respects its original alpha");
Check(SurfacePolicy.PanelAlpha(false,false,true,float.NaN)==.88f && SurfacePolicy.PanelAlpha(false,false,true,2)==1,"invalid opacity has bounded fallback");
var readable=SurfacePolicy.ReadableColor(new System.Numerics.Vector3(.1f,.2f,.3f));
Check(.2126f*readable.X+.7152f*readable.Y+.0722f*readable.Z>=.719f && readable.Z>readable.X,"dark accent is brightened while preserving hue order");
Check(SurfacePolicy.ReadableColor(System.Numerics.Vector3.One)==System.Numerics.Vector3.One,"already bright text is unchanged");
var outline=new NativeTextState();var textOriginal=new TextAppearance(0xFF123456,0x40);
var outlined=outline.Change("Inventory",1,2,textOriginal,true)!.Value;
Check(outlined.EdgeColor==0xE8000000 && outlined.Flags==0x48,"native text receives black outline while word wrap remains set");
outline.Change("Inventory",1,2,outlined,true);
Check(outline.Change("Inventory",1,2,outlined,false)==textOriginal,"restore native outline color and original edge state after repeated updates");
outline.Change("Inventory",1,2,textOriginal,true);
Check(outline.Change("Inventory",1,2,outlined with {Flags=0x4A},false)?.Flags==0x42,"preserve bold flag changed by game during outline ownership");
outline.Change("Inventory",1,2,textOriginal,true);
Check(outline.Change("Inventory",3,2,outlined,false)==null,"recreated addon never receives stale text style");
outline.Change("Inventory",1,2,textOriginal,true);outline.Forget("Inventory");
Check(outline.Change("Inventory",1,2,outlined,false)==null,"finalized text style identity is forgotten");
var priorEdge=new TextAppearance(0xFF888888,0x48);outline.Change("Inventory",1,2,priorEdge,true);
Check(outline.Change("Inventory",1,2,outlined,false)==priorEdge,"originally outlined text keeps its original outline on restoration");

Check(ChatPolicy.TryBuild("party","","hello",out var chatEntry,out _)&&chatEntry=="/party hello","party messages use fixed native chat command");
Check(ChatPolicy.TryBuild("tell","First Last@World","你好",out chatEntry,out _)&&chatEntry=="/tell First Last@World 你好","tell recipient with spaces and world is preserved");
Check(!ChatPolicy.TryBuild("tell","Name@World\n/say","hello",out _,out _)&&!ChatPolicy.TryBuild("tell","Name@World /say","hello",out _,out _),"control and command injection in recipients is rejected");
Check(!ChatPolicy.TryBuild("unknown","","hello",out _,out _)&&!ChatPolicy.TryBuild("say","","hello\n/world",out _,out _),"unknown routes and multiline input never reach game command processing");
Check(ChatPolicy.TryBuild("say","","/teleport",out chatEntry,out _)&&chatEntry=="/say /teleport","slash content remains a chat message under fixed route");
Check(!ChatPolicy.TryBuild("say","",new string('汉',150),out _,out _)&&ChatPolicy.TryBuild("say","",new string('汉',140),out _,out _),"full UTF-8 command length includes multibyte text and prefix");
Check(ChatPolicy.Routes.Count==25&&ChatPolicy.TryBuild("cwl8","","hello",out chatEntry,out _)&&chatEntry=="/cwlinkshell8 hello","cross-world and normal linkshell routes are enumerated explicitly");
Check(ChatPolicy.Matches(14,"Alice","hello",new ushort[]{14},"ALICE")&&!ChatPolicy.Matches(15,"Alice","hello",new ushort[]{14},""),"game channel filtering and case-insensitive search stay independent");
var normalChat=ChatGeometry.Compute(600,400,160,120,1,true);
Check(normalChat.Sidebar==160&&normalChat.Messages==434&&normalChat.Composer==120&&normalChat.Feed==264,"sidebar feed and composer dimensions account for splitters and spacing");
var narrowChat=ChatGeometry.Compute(220,160,600,300,1,true);
Check(narrowChat.Messages>0&&narrowChat.Feed>0&&narrowChat.Sidebar<220&&narrowChat.Composer<160,"narrow chat sizes cannot consume the message area");
var tabsChat=ChatGeometry.Compute(600,400,160,120,1,false);
Check(tabsChat.Sidebar==0&&tabsChat.Messages==600,"tabs or hidden navigation leave full message width");

var packed=ImageEffects.Pack(new byte[]{1,2,3,255,9,9,9,9,4,5,6,255},1,2,8);
Check(packed.Length==8&&packed[4]==4,"pack padded readback rows");
var solid=new byte[]{80,100,120,255,80,100,120,255};
Check(System.Linq.Enumerable.SequenceEqual(ImageEffects.Blur(solid,2,1,12),solid),"blur constant image with clamped edges");
Check(System.Linq.Enumerable.SequenceEqual(ImageEffects.Blur(solid,2,1,0),solid),"zero blur returns unchanged pixels");
var transparent=ImageEffects.Blur(new byte[]{255,0,0,0,0,0,255,255},2,1,1);
Check(transparent[0]==0&&transparent[4]==0&&transparent[2]>240,"premultiplied blur avoids transparent color bleed");
try{ImageEffects.Pack(new byte[4],2,1,8);Check(false,"invalid readback must reject");}catch(ArgumentException){Check(true,"reject incomplete readback");}

var top=TopBarLayout.Arrange(1000,8,new float[]{90,90,90},new float[]{100,100});
var ls=System.Linq.Enumerable.Where(top.Slots,s=>!s.Right).ToArray();var rs=System.Linq.Enumerable.Where(top.Slots,s=>s.Right).ToArray();
Check(ls.Length==3&&Math.Abs(ls[0].Width-ls[2].Width)<.01f,"shortcut cells distribute evenly");
Check(Math.Abs(rs[^1].X+rs[^1].Width-1000)<.01f&&ls[^1].X+ls[^1].Width<rs[0].X,"pinned information is right aligned without overlap");
var narrow=TopBarLayout.Arrange(320,8,new float[]{180,100,100,200},new float[]{150,180,90});
Check(narrow.Rows>1&&narrow.Slots.Count==7&&narrow.Slots.All(s=>s.X>=0&&s.X+s.Width<=320.01f),"narrow viewports wrap all entries within bounds");
Check(narrow.Slots.GroupBy(s=>s.Row).All(g=>g.OrderBy(s=>s.X).Zip(g.OrderBy(s=>s.X).Skip(1)).All(p=>p.First.X+p.First.Width<=p.Second.X+.01f)),"wrapped shortcut and pinned rows never overlap");
var unpinned=TopBarLayout.Arrange(500,8,new float[]{80,80},Array.Empty<float>());
Check(Math.Abs(unpinned.Slots[^1].X+unpinned.Slots[^1].Width-500)<.01f,"shortcuts use full width when pinned items hidden");
var rightOnly=TopBarLayout.Arrange(500,8,Array.Empty<float>(),new float[]{80,80});
Check(rightOnly.Slots[0].X>300&&rightOnly.Rows==1,"right only toolbar retains right alignment");

Check(HotbarPolicy.Name(0)=="_ActionBar"&&HotbarPolicy.Name(9)=="_ActionBar09","standard native hotbar mapping includes all ten addons");
Check(HotbarPolicy.Position(new(33,47),new(40),new(1920,1080),16,true)==new Vector2(32,48),"shift grid snaps both axes to nearest intersection");
Check(HotbarPolicy.Position(new(33,47),new(40),new(1920,1080),16,false)==new Vector2(33,47),"free drag retains one pixel precision without Shift");
Check(HotbarPolicy.Position(new(1900,1070),new(100),new(1920,1080),16,true)==new Vector2(1820,980),"snapping cannot move bars off screen");
Check(HotbarPolicy.Position(new(float.NaN,-30),new(3000,2000),new(1920,1080),float.NaN,true)==Vector2.Zero,"invalid coordinates and oversized bars stay bounded");
Check(HotbarPolicy.VisibilityCommand(9,true,out var showBar)&&showBar=="/hotbar display 10 on"&&!HotbarPolicy.VisibilityCommand(10,true,out _),"visibility uses fixed validated game command for one to ten bars");
var bounds=new (Vector2 Position,Vector2 Size)[]{(new(100,100),new(400,40)),(new(100,58),new(400,40))};
Check(HotbarPolicy.Handle(new(100,100),new(400,40),new(1920,1080),105,22,bounds,out var dragHandle)&&dragHandle.Y==142,"drag handles avoid slots in adjacent stacked bars");
var fullBounds=new (Vector2 Position,Vector2 Size)[]{(Vector2.Zero,new(1920,1080))};
Check(!HotbarPolicy.Handle(Vector2.Zero,new(1920,1080),new(1920,1080),105,22,fullBounds,out _),"no free handle area never overlays full screen skill slots");

var transforms=new NativeHotbarState();transforms.Original("_ActionBar",1,2,new(100,200),1);transforms.Original("_ActionBar",1,2,new(300,400),1.5f);
var restoredBar=transforms.Restore("_ActionBar",1,2);
Check(restoredBar?.Position==new Vector2(100,200)&&restoredBar.Scale==1,"restoring after repeated edits retains first native position and scale");
transforms.Original("_ActionBar",1,2,new(100,200),1);
Check(transforms.Restore("_ActionBar",3,4) is null,"recreated native bars never receive stale transforms");
transforms.Original("_ActionBar",1,2,new(100,200),1);transforms.Forget("_ActionBar");
Check(transforms.Restore("_ActionBar",1,2) is null,"finalizing hotbar forgets owned native transform");
transforms.Original("_ActionBar",1,2,new(100,200),1);transforms.Original("_ActionBar09",3,4,new(600,900),.8f);
Check(transforms.Restore("_ActionBar",1,2)?.Scale==1&&transforms.Restore("_ActionBar09",3,4)?.Scale==.8f,"multiple bars restore independent originals");

Check(VisualPolicy.IconSize(64,80,32)==new Vector2(32,40),"status artwork preserves portrait aspect ratio");
Check(VisualPolicy.Group(2,true,true)==EffectGroup.Debuff,"debuff category takes precedence over permanent flags");
Check(VisualPolicy.Group(1,false,false)==EffectGroup.Buff&&VisualPolicy.Group(1,true,false)==EffectGroup.Other,"permanent status grouped separately");
var flat=VisualPolicy.FlattenBgra(new byte[]{32,64,96,0},1,1);
Check(flat.SequenceEqual(new byte[]{96,64,32,0}),"flat icons preserve palette channels and transparent alpha");
Check(VisualPolicy.MapUv(Vector2.Zero,100,Vector2.Zero)==new Vector2(.5f),"map origin maps to texture center");
var crop=VisualPolicy.Crop(Vector2.Zero,1);
Check(crop.Min==Vector2.Zero&&crop.Max.X<=1&&crop.Max.Y<=1,"edge map crop stays within texture");
Check(!HudReplacementPolicy.ShouldHide("_NaviMap",HudReady.None)&&HudReplacementPolicy.ShouldHide("_NaviMap",HudReady.Minimap),"map replacement hides original only when ready");
